          {
            "id": "c34d9c3a-9c14-40fe-a0b5-a47dea44686c",
            "text": "Branding, legal writing, and payroll",
            "order": 2
          },
          {
            "id": "f992d642-d81a-42ff-85bb-4110fc5aed31",
            "text": "Marketing, tax filing, and recruiting",
            "order": 3
          },
          {
            "id": "e7455967-6673-4290-85a4-07e9cffcb50c",
            "text": "Procurement, logistics, and manufacturing",
            "order": 4
          }
        ]
      },
      {
        "id": "9ffd4aba-0207-43be-855e-3f392766f61f",
        "question_text": "What happens to the engagement economics problem as firms grow?",
        "question_type": "single",
        "options": [
          {
            "id": "5e8d0fa8-9ff8-4a25-a7f6-747196c4d60e",
            "text": "It disappears once enough software is added",
            "order": 1
          },
          {
            "id": "e5675130-6b39-49da-a2d7-9f93f3e8651b",
            "text": "It becomes easier because fewer staff are needed",
            "order": 2
          },
          {
            "id": "b4a871cc-0266-4ccb-97dc-60f3421f4336",
            "text": "It scales linearly with more engagements and more mechanical work",
            "order": 3
          },
          {
            "id": "8d971a34-74aa-4955-82f4-f74d7aa40d0e",
            "text": "It shifts entirely to planning instead of execution",
            "order": 4
          }
        ]
      },
      {
        "id": "212d6d5d-a8bc-42a5-b0e2-4176cf2c01bd",
        "question_text": "Which responsibility is specifically kept with auditors rather than AI?",
        "question_type": "single",
        "options": [
          {
            "id": "c2a7fd01-d709-4103-96fd-45324a9b209f",
            "text": "Extracting data points from documents",
            "order": 1
          },
          {
            "id": "2e41fc9f-4401-4082-ad7f-dae5046ea1cb",
            "text": "Flagging exceptions in evidence",
            "order": 2
          },
          {
            "id": "d8355f41-e91d-4728-9e4d-2aac123b7d9b",
            "text": "Determining whether evidence is sufficient and appropriate",
            "order": 3
          },
          {
            "id": "bcfc88d4-7978-4db5-8c1e-d72a3835f8b2",
            "text": "Comparing support to the general ledger",
            "order": 4
          }
        ]
      },
      {
        "id": "3521eb13-6c89-4cd4-90e4-b1e36ad47087",
        "question_text": "Why are issues separated into suggested items and items that need review?",
        "question_type": "single",
        "options": [
          {
            "id": "b3a25fc2-8612-4a3f-925e-d3f472bdc7f6",
            "text": "To let users apply all suggestions automatically without seeing any details",
            "order": 1
          },
          {
            "id": "efe25cf2-88d0-41e8-8e81-510ef241fd76",
            "text": "To organize results by what AI recommends versus what requires closer attention",
            "order": 2
          },
          {
            "id": "7f47fa7f-85cd-4411-b014-9134a66dea90",
            "text": "To hide small differences from the reviewer",
            "order": 3
          },
          {
            "id": "344563a7-9c3a-4f01-ba15-687704f8cc68",
            "text": "To prevent reviewers from making manual changes",
            "order": 4
          }
        ]
      },
      {
        "id": "1e16b3f8-4e0b-455a-9853-cbd396d737d0",
        "question_text": "What is one reason the tool can find errors quickly in financial statements?",
        "question_type": "single",
        "options": [
          {
            "id": "01d58739-a142-464b-a887-663eb21debc8",
            "text": "It checks every number individually across the document",
            "order": 1
          },
          {
            "id": "34848a83-34bc-4f1b-86ef-8435e80e93fa",
            "text": "It reviews only the notes section",
            "order": 2
          },
          {
            "id": "57a69cc6-0158-40ab-9a88-8a2db036a294",
            "text": "It focuses only on totals above a set threshold",
            "order": 3
          },
          {
            "id": "f1f6cd0d-1157-48fd-b69e-b65212cb3db2",
            "text": "It skips repeated values",
            "order": 4
          }
        ]
      },
      {
        "id": "285ea914-9880-4f5a-94dd-4a0d9c801ad9",
        "question_text": "How are engagement comments shared with other team members?",
        "question_type": "single",
        "options": [
          {
            "id": "c7f08397-4e9e-4596-8bec-e5a8f73bb193",
            "text": "They are posted publicly to the client portal",
            "order": 1
          },
          {
            "id": "544c6f6f-6348-4a89-8971-9cfdc641d309",
            "text": "They are sent in batched email updates",
            "order": 2
          },
          {
            "id": "5e0294e3-95b0-40b3-a68b-31e4454dda50",
            "text": "They are printed automatically with the financials",
            "order": 3
          },
          {
            "id": "db3b631b-b95e-4191-9485-26a35062f5ae",
            "text": "They are converted into checklist items only",
            "order": 4
          }
        ]
      },
      {
        "id": "4e8b1874-fdc0-45db-a759-c7a43e870a9d",
        "question_text": "What does an AI agent return after executing procedures on evidence?",
        "question_type": "single",
        "options": [
          {
            "id": "795ae616-0004-42a5-995c-c06c4331fd6c",
            "text": "General advice with no support",
            "order": 1
          },
          {
            "id": "1bfe303f-f8ec-42b9-858c-cfbb5d0c370c",
            "text": "Results with citations back to source documents",
            "order": 2
          },
          {
            "id": "2b293758-b96d-4b63-affe-2982403151b4",
            "text": "Only a final opinion",
            "order": 3
          },
          {
            "id": "1dec90bb-cec7-42e9-aad2-c9d617f0f1db",
            "text": "Verbal feedback without documentation",
            "order": 4
          }
        ]
      },
      {
        "id": "9ef21eb9-efea-49c2-a38b-e3afafabd5b0",
        "question_text": "What three things does the platform connect after the audit approach is set?",
        "question_type": "single",
        "options": [
