          {
            "id": "59fb473d-00b5-4039-936c-31826c00a146",
            "text": "Planning memo, engagement letter, and tax return",
            "order": 2
          },
          {
            "id": "73c403d4-60a9-4de5-b8da-08dd8a708284",
            "text": "Pricing model, invoice, and payroll file",
