        "horizontal_thumbnail_url": "https://milesone-backend-assets.s3.ap-south-1.amazonaws.com/MilesOne/Masterclass/Chapter_Thumbnails/Horizontal/agentive6.jpg",
        "vertical_thumbnail_url": null,
